// Service worker: keeps the app working offline. Generated by tools/build.mjs – edit the template, not sw.js.
const VERSION = 'e334941f23';
const SHELL = 'shell-' + VERSION;
const RUNTIME = 'runtime-v1';
const ASSETS = [
 "./",
 "css/app.css",
 "icons/apple-touch-icon.png",
 "icons/icon-192.png",
 "icons/icon-512.png",
 "icons/icon-maskable-512.png",
 "icons/icon.svg",
 "index.html",
 "js/app.js",
 "js/cloud.js",
 "js/data/ingredients.js",
 "js/data/recipes/asian.js",
 "js/data/recipes/classics.js",
 "js/data/recipes/everyday.js",
 "js/data/recipes/world.js",
 "js/docx.js",
 "js/ocr.js",
 "js/online.js",
 "js/planner.js",
 "js/recipes-core.js",
 "js/recipes.js",
 "js/shopping.js",
 "js/store.js",
 "js/sync.js",
 "js/themes.js",
 "js/ui.js",
 "js/units.js",
 "js/views/cookbook.js",
 "js/views/more.js",
 "js/views/pantry.js",
 "js/views/plan.js",
 "js/views/recipe.js",
 "js/views/setup.js",
 "js/views/shop.js",
 "js/weather.js",
 "manifest.webmanifest",
 "vendor/fonts/OFL-Caveat.txt",
 "vendor/fonts/OFL-Fraunces.txt",
 "vendor/fonts/OFL-Nunito.txt",
 "vendor/fonts/caveat-latin-500-normal.woff2",
 "vendor/fonts/caveat-latin-700-normal.woff2",
 "vendor/fonts/fraunces-latin-400-italic.woff2",
 "vendor/fonts/fraunces-latin-400-normal.woff2",
 "vendor/fonts/fraunces-latin-600-normal.woff2",
 "vendor/fonts/fraunces-latin-700-normal.woff2",
 "vendor/fonts/nunito-latin-400-normal.woff2",
 "vendor/fonts/nunito-latin-600-normal.woff2",
 "vendor/fonts/nunito-latin-700-normal.woff2",
 "vendor/fonts/nunito-latin-800-normal.woff2",
 "vendor/qrcode/qrcode.mjs"
];

self.addEventListener('install', e => {
  e.waitUntil(caches.open(SHELL).then(c => c.addAll(ASSETS)).then(() => self.skipWaiting()));
});

self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('shell-') && k !== SHELL).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});

self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  // Live data (weather, online recipes, sync) always goes to the network.
  if (/open-meteo\.com|themealdb\.com\/api|firestore|googleapis|gstatic\.com\/firebasejs/.test(url.href)) return;
  if (url.origin === location.origin) {
    // App files: from the offline copy, falling back to the network (and keeping big extras like the photo reader).
    e.respondWith(caches.match(req, { ignoreSearch: true }).then(hit => hit || fetch(req).then(res => {
      if (res.ok && /\/vendor\/tesseract\//.test(url.pathname)) { const copy = res.clone(); caches.open(RUNTIME).then(c => c.put(req, copy)); }
      return res;
    }).catch(() => req.mode === 'navigate' ? caches.match('./') : Response.error())));
    return;
  }
  // Recipe photos: keep a copy once seen.
  if (/themealdb\.com\/images/.test(url.href)) {
    e.respondWith(caches.open(RUNTIME).then(c => c.match(req).then(hit => hit || fetch(req).then(res => { if (res.ok || res.type === 'opaque') c.put(req, res.clone()); return res; }))));
  }
});
